// Reproduce the “.0” precision bug in the DOM Size audit
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');
(async () => {
  // Launch headless Chrome
  const chrome = await chromeLauncher.launch({chromeFlags: ['--headless']});
  const options = {
    logLevel: 'info',
    port: chrome.port,
    onlyAudits: ['dom-size'],      // run only the DOM Size audit
    output: 'json'
  };
  // Create an HTML page with a large, nested DOM
  const html = `
    <html><head><title>DOM Size Test</title></head>
    <body>
      ${'<div>'.repeat(150)}${'</div>'.repeat(150)}
    </body></html>
  `;
  const url = 'data:text/html;charset=utf-8,' + encodeURIComponent(html);
  // Run Lighthouse
  const runnerResult = await lighthouse(url, options);
  const lhr = runnerResult.lhr;
  // Extract the DOM Size audit result
  const domSize = lhr.audits['dom-size'];
  console.log('Display value:', domSize.displayValue);
  console.log('Details items:');
  domSize.details.items.forEach(item => {
    console.log(
      `${item.statistic}: ${item.value}  (raw numericValue: ${item.numericValue})`)
  });
  await chrome.kill();
})();
